 public function markPaid(int$a,int$id,int$revision,string$date,string$op):array{return$this->operation($a,$op,['pay',$id,$revision,$date],function()use($a,$id,$revision,$date){$this->authorize($a);$r=$this->locked($id);$this->revision($r,$revision);if($r['status']!=='accepted')throw new \DomainException('CALCULATION_IMMUTABLE');$projection=$this->decode($r['projection_json']);$this->admit($this->decode($r['input_json']),'payment',$projection['admission']??[]);if($date>substr(($this->clock)(),0,10))throw new \DomainException('FUTURE_PAYMENT_DATE');$existing=$this->activePaymentFor($id);if($existing!==false)return['status'=>'no_change','calculationId'=>$id,'revision'=>(int)$r['revision'],'paidCents'=>(int)$existing['amount_cents'],'paymentId'=>(int)$existing['id']];$amount=(int)$this->db->createCommand("SELECT COALESCE(SUM(amount_cents),0) FROM `{$this->prefix}fm2_otiz_recipient_obligations` WHERE calculation_id=:id",[':id'=>$id])->queryScalar();$this->db->createCommand("INSERT INTO `{$this->prefix}fm2_otiz_payment_facts`(calculation_id,amount_cents,payment_date,created_at)VALUES(:id,:a,:d,:at)",[':id'=>$id,':a'=>$amount,':d'=>$date,':at'=>($this->clock)()])->execute();$pid=(int)$this->db->getLastInsertID();$this->event($id,'paid',$a,['paymentId'=>$pid]);return['status'=>'completed','calculationId'=>$id,'revision'=>(int)$r['revision'],'paidCents'=>$amount,'paymentId'=>$pid];});}
