 private function acceptInside(int$a,int$id,int$revision,bool$replacement):array{$this->authorize($a);$r=$this->locked($id);$this->draftRevision($r,$revision);$input=$this->decode($r['input_json']);$admission=$this->admit($input,'accept');$p=$this->decode($r['projection_json']);foreach($p['objects']??[]as$projected)if(($projected['calculationState']??'ready')==='blocked')throw new \DomainException('NO_ELIGIBLE_RECIPIENT');$p['admission']=$admission;$this->db->createCommand("UPDATE `{$this->prefix}fm2_otiz_calculation_revisions` SET projection_json=:p WHERE id=:id",[':p'=>$this->json($p),':id'=>$id])->execute();foreach($input['objects']??[]as$o)foreach($o['entitlements']??[]as$e){if(array_key_exists('active',$e)&&!$e['active'])continue;try{$this->db->createCommand("INSERT INTO `{$this->prefix}fm2_otiz_entitlement_claims`(calculation_id,object_id,source_kind,source_id,source_revision,entitlement_kind,recognition_date,gross_cents)VALUES(:c,:o,:k,:s,:r,:e,:d,:g)",[':c'=>$id,':o'=>$o['objectId'],':k'=>$e['sourceKind'],':s'=>$e['sourceId'],':r'=>$e['sourceRevision'],':e'=>$e['kind'],':d'=>$e['recognitionDate'],':g'=>$e['grossCents']])->execute();}catch(\yii\db\IntegrityException$e){throw new \DomainException('ENTITLEMENT_ALREADY_ACCEPTED');}}
