 private function project(array$input,array$deductions,array$decisions):array{$all=[];$objects=[];$total=0;$decisionMap=[];foreach($decisions as$d)$decisionMap[$d['employeeId']]=$d['decision'];foreach($input['objects']??[]as$o){$oid=(int)$o['objectId'];$gross=0;foreach($o['entitlements']??[]as$e)if(($e['active']??true)&&!$this->claimExists($e))$gross+=(int)$e['grossCents'];$deadline=isset($o['deadlineBp'])?intdiv($gross*(10000-(int)$o['deadlineBp']),10000):0;$common=0;$personal=[];foreach($deductions as$d)if((int)$d['objectId']===$oid){if($d['employeeId']===null)$common+=(int)$d['amountCents'];else$personal[$d['employeeId']]=($personal[$d['employeeId']]??0)+(int)$d['amountCents'];}$pool=max(0,$gross-$deadline-$common);$excluded=[];foreach($o['recipients']??[]as$e)if(($decisionMap[(string)$e['employeeId']]??'pay')==='do_not_pay')$excluded[]=(string)$e['employeeId'];$originalAmounts=($o['recipients']??[])===[]?[]:OtizSettlementV2Math::allocate($pool,$o['recipients']??[],[],[]);$preAmounts=($o['recipients']??[])===[]?[]:OtizSettlementV2Math::allocate($pool,$o['recipients']??[],$excluded,[]);$amounts=($o['recipients']??[])===[]?[]:OtizSettlementV2Math::allocate($pool,$o['recipients']??[],$excluded,$personal);foreach($o['recipients']??[]as$e){$eid=(string)$e['employeeId'];$all[]=['objectId'=>$oid,'employeeId'=>$eid,'tabNumber'=>(string)$e['tabNumber'],'name'=>(string)$e['name'],'employment'=>$e['employment']??'unknown','weight'=>(int)$e['weight'],'decision'=>$decisionMap[$eid]??'pay','originalContributionCents'=>$originalAmounts[$eid]??0,'preDeductionCents'=>$preAmounts[$eid]??0,'deductionCents'=>$personal[$eid]??0,'excluded'=>in_array($eid,$excluded,true),'amountCents'=>$amounts[$eid]??0];}$payable=array_sum($amounts);$objects[]=['objectId'=>$oid,'regnumber'=>(string)($o['regnumber']??$oid),'fundCents'=>$o['fundCents']??null,'plannedPremiumCents'=>$o['plannedPremiumCents']??null,'grossCents'=>$gross,'deadlineCents'=>$deadline,'disciplineCents'=>$common,'payableCents'=>$